package com.paitrick.blog.auth.service; import com.paitrick.blog.common.config.AppProperties; import com.paitrick.blog.common.exception.BusinessException; import com.paitrick.blog.common.security.JwtService; import com.paitrick.blog.auth.dto.LoginRequest; import org.springframework.stereotype.Service;
@Service public class AuthService{private final AppProperties p;private final JwtService jwt;public AuthService(AppProperties p,JwtService jwt){this.p=p;this.jwt=jwt;}public String login(LoginRequest r){if(!p.admin().username().equals(r.username())||!p.admin().password().equals(r.password()))throw new BusinessException("invalid username or password");return jwt.create(r.username());}}
